class RocMomentum(Strategy):
    name = "roc_momentum"
    LOOKBACK = 20
    THRESHOLD = 0.02
    warmup_bars = 30

    def on_bar(self, symbol, store):
        window = store.window(symbol, self.timeframe)
        if len(window) < self.warmup_bars:
            return math.nan
        closes = window.closes()
        if len(closes) <= self.LOOKBACK:
            return math.nan
        roc = (closes[-1] - closes[-self.LOOKBACK-1]) / closes[-self.LOOKBACK-1]
        if not math.isfinite(roc):
            return math.nan
        if roc > self.THRESHOLD:
            return 1.0
        if roc < -self.THRESHOLD:
            return -1.0
        return 0.0
